229	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
230	    write_csr_tolerant(kCsrMepc,   state.mepc);
231	    write_csr_tolerant(kCsrMcause, state.mcause);
232	    write_csr_tolerant(kCsrMtval,  state.mtval);
233	    write_csr_tolerant(kCsrMie,    state.mie);
234	    write_csr_tolerant(kCsrMip,    state.mip);
235	
236	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
237	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
238	    // caches) but has no cache model, so without this the cycle engine resumes
239	    // at the ROI with caches at their reset default -- DISABLED -- and the
240	    // whole measured window runs uncached, inflating it severalfold. Tolerant
241	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
242	    // write as a no-op, and a drained 0 (caches were off) restores the reset
243	    // state, so this is always safe to issue.
244	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
245	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
246	
247	    // Andes V5 CSR block (v3): the boot-static memory-system / extension CSRs
248	    // the functional engine set up before the ROI -- PMA attributes, mxstatus,
249	    // ILM/DLM bases, perf throttling, stack-protection bounds, the CoDense/Zcmt
250	    // table bases -- plus the DSP overflow flag (ucode). Same rationale as
251	    // mcache_ctl: without them the cycle engine resumes with the wrong memory
252	    // system or faults on the first CoDense/DSP op in the window. caps_ gates
253	    // each write to the CSRs the TARGET core actually implements (from its
254	    // config.inc): restoring an absent custom CSR is NOT a clean no-op -- the
255	    // abstract write stalls the DM handshake (observed: ucode without DSP,
256	    // mecc_code without ECC). HYBRID_ANDES_CSR_LIST is the single source of
257	    // truth shared with the plugin drain, StateDrain, and state_diff.
258	    if (state.flags & HYBRID_FLAG_ANDES) {
259	#define X(field, addr, name) \
260	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
261	      HYBRID_ANDES_CSR_LIST(X)
262	#undef X
263	      // PMA: every pmaaddr before any pmacfg (a TOR/NAPOT cfg consumes the addr
264	      // already in place -- mirror the PMP ordering). On RV64 only even pmacfg
265	      // CSRs exist, so slot i maps to 0xBC0 + 2*i; pmaaddr i maps to 0xBD0 + i.
266	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
