270	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
271	          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
272	    }
273	
274	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
275	    // from QEMU1's drain value. Without this, vsim's local counter starts
276	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
