278	    // overwrite here as the GPR loop already ran.
279	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
280	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
281	
282	    clear_cmderr_if_set();
283	    request_resume();
284	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
285	                   "ResumeDriver resume");
